//! Corpus equipment and equipment-modifier records that belong to an
//! ALREADY-COMPILED book whose hand-authored per-book table does not hold
//! them — the `not-ingested` population of `docs/work-inventory.json`'s
//! `equipment`/`equipment_modifier` kinds, closed corpus-wide.
//!
//! **GENERATED — do not edit by hand.** Regenerate with
//! `PCGEN_CORPUS_ROOT=<pcgen>/data cargo run --locked --bin gen_equipment_gap_tables`.
//! The generator applies `v06_work_inventory`'s own record predicate, so a
//! row here is exactly a row that inventory reported `not-ingested`.
//!
//! `cost_gp`/`weight_lbs` are `None` when the corpus record carries no such
//! token, or carries a PCGen formula this table deliberately does not
//! evaluate — never a fabricated flat number. `description` joins the
//! record's `DESC:` and `SPROP:` tokens when both are present. A `.COPY=`
//! row that states none of `description`/`cost_gp`/`weight_lbs` on its own
//! line inherits them from the base record it declares itself a copy of
//! (`SD31-E6-F6-001`, `OPEN-ISSUES.md` rows 70/103) — never fabricated,
//! never inherited past one hop.
//!
//! `decisions.md §24`: a row whose real `key`/`name` is Product Identity
//! (declared `NAMEISPI:YES` or a blacklist hit) is no longer excluded
//! whole — it is INCLUDED under a Codex-generated neutral `key`/`name`
//! (`name_pi_citation` is `Some` for exactly these rows).
//!
//! Total: 1973 rows.

/// One recovered corpus equipment row. Deliberately one flat shape for
/// every book: unlike the hand-authored per-book tables (each with its own
/// `EquipmentCategory` enum and field set), these rows exist to be chained
/// into `equipment_resolver::equipment_catalog_rows()` and rendered by the
/// desktop equipment catalog, both of which read exactly these fields.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct EquipmentGapRow {
    /// One of `equipment_resolver`'s `EQUIPMENT_BOOK_*` codes.
    pub book: &'static str,
    /// The record's `KEY:` token when it carries one, else its display name.
    pub key: &'static str,
    pub name: &'static str,
    /// The catalog category, matching the `EquipmentCategory` variant names
    /// the per-book tables project onto `EquipmentCatalogEntryDto::category`.
    pub category: &'static str,
    pub cost_gp: Option<f64>,
    pub weight_lbs: Option<f64>,
    pub description: Option<&'static str>,
    /// `decisions.md §24`: `Some((source_file, source_line))`
    /// ONLY when `key`/`name` above are a Codex-generated neutral
    /// identity (the row's real name/key is Product Identity) --
    /// carries the real citation so `cache_gen::equipment_gap::
    /// generate` can resolve it directly instead of text-searching
    /// for a `key`/`name` the real corpus no longer contains.
    /// `source_file` is relative to the book's own directory.
    /// `None` for an ordinary row.
    pub name_pi_citation: Option<(&'static str, u32)>,
}

/// Every recovered row, in book order. The order is load-bearing the same
/// way `equipment_catalog_rows()`'s is: first match wins for key lookup.
pub fn equipment_gap_rows() -> impl Iterator<Item = &'static EquipmentGapRow> {
    [CORE_RULEBOOK_GAP_ROWS, BESTIARY_GAP_ROWS, ADVANCED_PLAYERS_GUIDE_GAP_ROWS, ADVANCED_CLASS_GUIDE_GAP_ROWS, ADVANCED_RACE_GUIDE_GAP_ROWS, ULTIMATE_COMBAT_GAP_ROWS, ULTIMATE_INTRIGUE_GAP_ROWS, ULTIMATE_EQUIPMENT_GAP_ROWS, ULTIMATE_PSIONICS_GAP_ROWS, ULTIMATE_WILDERNESS_GAP_ROWS, OCCULT_ADVENTURES_GAP_ROWS, HORROR_ADVENTURES_GAP_ROWS, INNER_SEA_RACES_GAP_ROWS, INNER_SEA_WORLD_GUIDE_GAP_ROWS, MONSTER_CODEX_GAP_ROWS, BESTIARY_2_GAP_ROWS, BESTIARY_3_GAP_ROWS, BESTIARY_4_GAP_ROWS, INNER_SEA_GODS_GAP_ROWS, MYTHIC_ADVENTURES_GAP_ROWS, INNER_SEA_COMBAT_GAP_ROWS, INNER_SEA_INTRIGUE_GAP_ROWS, BOOK_OF_THE_DAMNED_VOLUME_2_GAP_ROWS, INNER_SEA_TEMPLES_GAP_ROWS, INNER_SEA_MAGIC_GAP_ROWS, ADVENTURERS_GUIDE_GAP_ROWS, ULTIMATE_MAGIC_GAP_ROWS, BEGINNER_BOX_GAP_ROWS]
        .into_iter()
        .flat_map(|rows| rows.iter())
}

